import{_ as l,o as t,c as s,a0 as e}from"./chunks/framework.DYAX5gPL.js";const y=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"api/includes/geometry-methods.md","filePath":"api/includes/geometry-methods.md"}'),r={name:"api/includes/geometry-methods.md"};function o(a,i,p,m,u,n){return t(),s("div",null,[...i[0]||(i[0]=[e('<h2 id="继承自marker的方法" tabindex="-1">继承自Marker的方法 <a class="header-anchor" href="#继承自marker的方法" aria-label="Permalink to &quot;继承自Marker的方法&quot;">​</a></h2><details><summary>getCoordinates()</summary><div><br><p>获取坐标。</p><p>返回：</p><ul><li>Coordinate</li></ul></div></details><details><summary>setCoordinates(coordinates)</summary><div><br><p>设置坐标。</p><p>参数：</p><ul><li>coordinates <strong>Number[]</strong> | <strong>Coordinate</strong> 新的坐标</li></ul><p>返回：</p><ul><li>this</li></ul></div></details><details><summary>getFirstCoordinate()</summary><div><br><p>获取第一个坐标。</p><p>返回：</p><ul><li>Coordinate</li></ul></div></details><details><summary>getLastCoordinate()</summary><div><br><p>获取最后一个坐标。</p><p>返回：</p><ul><li>Coordinate</li></ul></div></details><details><summary>addTo(layer)</summary><div><br><p>添加到图层上。</p><p>参数：</p><ul><li>layer <strong>Layer</strong> 图层</li></ul><p>返回：</p><ul><li>this</li></ul></div></details><details><summary>getLayer()</summary><div><br><p>获取添加到的图层。</p><p>返回：</p><ul><li>Layer</li></ul></div></details><details><summary>getMap()</summary><div><br><p>获取添加到的地图。</p><p>返回：</p><ul><li>Map</li></ul></div></details><details><summary>getId()</summary><div><br><p>获取Geometry的id。</p><p>返回：</p><ul><li>String | Number</li></ul></div></details><details><summary>setId(id)</summary><div><br><p>设置新的id。</p><p>参数：</p><ul><li>id <strong>Number</strong> | <strong>String</strong> 新的id</li></ul><p>返回：</p><ul><li>this</li></ul></div></details><details><summary>getProperties()</summary><div><br><p>获取Geometry的属性数据。</p><p>返回：</p><ul><li>Object</li></ul></div></details><details><summary>setProperties(properties)</summary><div><br><p>给Geometry设置属性数据。</p><p>参数：</p><ul><li>properties <strong>Object</strong> 新的属性数据</li></ul><p>返回：</p><ul><li>this</li></ul></div></details><details><summary>getType()</summary><div><br><p>获取Geometry的type。</p><p>返回：</p><ul><li>String</li></ul></div></details><details><summary>getSymbol()</summary><div><br><p>获取Geometry的symbol样式。</p><p>返回：</p><ul><li>Object</li></ul></div></details><details><summary>setSymbol(symbol)</summary><div><br><p>给Geometry设置新的symbol样式。</p><p>参数：</p><ul><li>symbol <strong>Object</strong> 新的样式对象</li></ul><p>返回：</p><ul><li>Object</li></ul></div></details><details><summary>updateSymbol(symbol)</summary><div><br><p>更新Geometry的symbol样式。</p><p>参数：</p><ul><li>symbol <strong>Object</strong> 要更新的symbol属性</li></ul><p>返回：</p><ul><li>Object</li></ul></div></details><details><summary>getCenter()</summary><div><br><p>获取Geometry的地理重心。</p><p>返回：</p><ul><li>Coordinate</li></ul></div></details><details><summary>getExtent()</summary><div><br><p>获取Geometry的地理范围。</p><p>返回：</p><ul><li>Extent</li></ul></div></details><details><summary>show()</summary><div><br><p>显示Geometry。</p><p>返回：</p><ul><li>this</li></ul></div></details><details><summary>hide()</summary><div><br><p>隐藏Geometry。</p><p>返回：</p><ul><li>this</li></ul></div></details><details><summary>isVisible()</summary><div><br><p>Geometry是否显示。</p><p>返回：</p><ul><li>Boolean</li></ul></div></details><details><summary>getZIndex()</summary><div><br><p>返回Geometry的zIndex。</p><p>返回：</p><ul><li>Number</li></ul></div></details><details><summary>setZIndex(zIndex)</summary><div><br><p>设置Geometry的zIndex。</p><p>参数：</p><ul><li>zIndex <strong>Number</strong> Geometry的zIndex</li></ul><p>返回：</p><ul><li>this</li></ul></div></details><details><summary>setZIndexSilently(zIndex)</summary><div><br><p>只设置Geometry的zIndex，但不会触发图层的重绘。 如果有大量Geoemtry的zIndex要更新，可以调用setZIndexSilently来更新，在最后一个Geometry调用setZIndex来出发图层的重绘，这样能提升性能。</p><p>参数：</p><ul><li>zIndex <strong>Number</strong> Geometry的zIndex</li></ul><p>返回：</p><ul><li>this</li></ul></div></details><details><summary>translate(x, y)</summary><div><br><p>用给定的x和y偏移量移动Geometry。</p><p>参数：</p><ul><li>x <strong>Number</strong> x轴上的偏移量</li><li>y <strong>Number</strong> y轴上的偏移量</li></ul><p>返回：</p><ul><li>this</li></ul></div></details><details><summary>flash(interval, count, cb, context)</summary><div><br><p>按照给定的参数间隔消失，显示，闪动Geometry。</p><p>参数：</p><ul><li>interval <strong>Number</strong> 间隔时间</li><li>count <strong>Number</strong> 次数</li><li>cb <strong>Function</strong> 闪烁结束后的回调函数</li><li>context <strong>Object</strong> 回调函数运行时使用的this值</li></ul><p>返回：</p><ul><li>this</li></ul></div></details><details><summary>copy()</summary><div><br><p>复制一个Geometry。</p><p>返回：</p><ul><li>Geometry</li></ul></div></details><details><summary>remove()</summary><div><br><p>从图层上移除Geometry。</p><p>返回：</p><ul><li>this</li></ul></div></details><details><summary>toGeoJSONGeometry()</summary><div><br><p>转换成GeoJSON的geometry对象。</p><p>返回：</p><ul><li>Object</li></ul></div></details><details><summary>toGeoJSON(options)</summary><div><br><p>转换成GeoJSON的对象。</p><p>参数：</p><ul><li>options <strong>Object</strong> 导出配置</li><li>options.geometry <strong>Boolean</strong> 是否导出geometry，默认是true</li><li>options.properties <strong>Boolean</strong> 是否导出properties，默认是true</li></ul><p>返回：</p><ul><li>Object</li></ul></div></details><details><summary>toJSON(options)</summary><div><br><p>转换成JSON对象。</p><p>该对象可以用 Geometry.fromJSON(json) 创建一个Geometry对象。</p><p>参数：</p><ul><li>options <strong>Object</strong> 导出配置</li><li>options.geometry <strong>Boolean</strong> 是否导出geometry，默认是true</li><li>options.properties <strong>Boolean</strong> 是否导出properties，默认是true</li><li>options.options <strong>Boolean</strong> 是否导出构造options，默认是true</li><li>options.symbol <strong>Boolean</strong> 是否导出symbol，默认是true</li><li>options.infoWindow <strong>Boolean</strong> 是否导出InfoWindow设置，默认是true</li></ul><p>返回：</p><ul><li>Object</li></ul></div></details><details><summary>getLength()</summary><div><br><p>返回Geometry的地理长度。</p><p>返回：</p><ul><li>Number</li></ul></div></details><details><summary>getArea()</summary><div><br><p>返回Geometry的地理面积。</p><p>返回：</p><ul><li>Number</li></ul></div></details><details><summary>rotate(angle, pivot)</summary><div><br><p>绕着 pivot 坐标旋转 angle 角度。</p><p>参数：</p><ul><li>angle* <strong>Number</strong> 渲染角度，单位度</li><li>pivot <strong>Coordinate</strong> 渲染中心点</li></ul><p>返回：</p><ul><li>this</li></ul></div></details><details><summary>startEdit(options)</summary><div><br><p>开始编辑图形。</p><p>参数：</p><ul><li>options <strong>Object</strong> 编辑参数</li><li>options.symbol <strong>Object</strong> 编辑状态的图形样式</li><li>options.fixAspectRatio <strong>Boolean</strong> 如果图形有高宽，则固定图形的高宽比</li><li>options.centerHandleSymbol <strong>Object</strong> 图形中心拖动手柄的样式（如果存在）</li><li>options.vertexHandleSymbol <strong>Object</strong> 端点拖动手柄的样式（如果存在）</li><li>options.newVertexHandleSymbol <strong>Object</strong> 新建端点手柄的样式（如果存在）</li><li>options.centerHandleSymbol <strong>Object</strong> 图形中心拖动手柄的样式（如果存在）</li></ul><p>返回：</p><ul><li>this</li></ul></div></details><details><summary>endEdit()</summary><div><br><p>停止编辑。</p><p>返回：</p><ul><li>this</li></ul></div></details><details><summary>redoEdit()</summary><div><br><p>重做上一步编辑操作。</p><p>返回：</p><ul><li>this</li></ul></div></details><details><summary>undoEdit()</summary><div><br><p>撤销上一步编辑操作。</p><p>返回：</p><ul><li>this</li></ul></div></details><details><summary>cancelEdit()</summary><div><br><p>取消编辑，让图形回到最初状态。</p><p>返回：</p><ul><li>this</li></ul></div></details><details><summary>isEditing()</summary><div><br><p>图形是否处于编辑状态中。</p><p>返回：</p><ul><li>this</li></ul></div></details><details><summary>isDragging()</summary><div><br><p>图形是否处于拖拽状态中。</p><p>返回：</p><ul><li>this</li></ul></div></details><details><summary>animate(styles, options, step)</summary><div><br><p>按照给定的参数执行图形动画。</p><p>参数：</p><ul><li>styles* <strong>Object</strong> 要执行动画的属性，例如symbol或是translate</li><li>options <strong>Object</strong> 动画设置</li><li>options.duration <strong>Number</strong> 持续时间，单位ms，默认1000</li><li>options.startTime <strong>Number</strong> 开始动画的时间</li><li>options.easing <strong>String</strong> 动画缓动类型，缓动类型可以参考<a href="https://github.com/fuzhenn/animation-easings" target="_blank" rel="noreferrer">animation-easings</a>中的说明。</li><li>options.repeat <strong>Boolean</strong> 动画结束后是否重复播放</li></ul><p>返回：</p><ul><li>this</li></ul></div></details><details><summary>setInfoWindow(options)</summary><div><br><p>给图形设置弹出信息框。</p><p>参数：</p><ul><li>options <strong>Object</strong> 信息框设置</li><li>options.title <strong>String</strong> 信息框标题</li><li>options.content <strong>String</strong> 信息框内容</li></ul><p>其他设置可以参考<a href="https://maptalks.org/maptalks.js/api/0.x/ui.InfoWindow.html" target="_blank" rel="noreferrer">InfoWindow</a>中的说明和<a href="https://maptalks.org/examples/cn/ui-control/ui-custom-infownd/#ui-control_ui-custom-infownd" target="_blank" rel="noreferrer">示例</a></p><p>返回：</p><ul><li>this</li></ul></div></details><details><summary>getInfoWindow()</summary><div><br><p>返回Geometry的InfoWindow对象实例。</p><p>返回：</p><ul><li>InfoWindow</li></ul></div></details><details><summary>openInfoWindow(coordinates)</summary><div><br><p>打开图形的信息框。</p><p>参数：</p><ul><li>coordinates <strong>Coordiante | Number[]</strong> 可选的信息框坐标。</li></ul><p>返回：</p><ul><li>this</li></ul></div></details><details><summary>closeInfoWindow()</summary><div><br><p>关闭InfoWindow信息框。</p><p>返回：</p><ul><li>this</li></ul></div></details><details><summary>removeInfoWindow()</summary><div><br><p>移除图形的InfoWindow信息框。</p><p>返回：</p><ul><li>this</li></ul></div></details><details><summary>setMenu(options)</summary><div><br><p>给图形设置右键菜单。</p><p>参数：</p><ul><li>options <strong>Object</strong> 菜单设置</li><li>options.width <strong>Number</strong> 菜单宽度</li><li>options.items <strong>Object[]</strong> 菜单项</li><li>options.items.item <strong>String</strong> 菜单显示标题</li><li>options.items.click <strong>Function</strong> 响应函数</li></ul><p>其他设置可以参考<a href="https://maptalks.org/maptalks.js/api/0.x/ui.Menu.html" target="_blank" rel="noreferrer">Menu</a>中的说明和<a href="https://maptalks.org/examples/cn/ui-control/ui-custom-menu/#ui-control_ui-custom-menu" target="_blank" rel="noreferrer">示例</a></p><p>返回：</p><ul><li>this</li></ul></div></details><details><summary>openMenu(coordinates)</summary><div><br><p>打开图形的右键菜单。</p><p>参数：</p><ul><li>coordinates <strong>Coordiante | Number[]</strong> 可选的菜单坐标。</li></ul><p>返回：</p><ul><li>this</li></ul></div></details><details><summary>setMenuItems(items)</summary><div><br><p>给图形设置右键菜单中的菜单项。</p><p>参数：</p><ul><li>items <strong>Object[]</strong> 菜单项</li><li>items.item <strong>String</strong> 菜单显示标题</li><li>items.click <strong>Function</strong> 响应函数</li></ul><p>返回：</p><ul><li>this</li></ul></div></details><details><summary>getMenuItems()</summary><div><br><p>返回图形的右键菜单的菜单项。</p><p>返回：</p><ul><li>Object[]</li></ul></div></details><details><summary>closeMenu()</summary><div><br><p>关闭右键菜单。</p><p>返回：</p><ul><li>this</li></ul></div></details><details><summary>removeMenu()</summary><div><br><p>移除右键菜单。</p><p>返回：</p><ul><li>this</li></ul></div></details><details><summary>on(events, handler, context)</summary><div><br><p>注册图形的监听事件</p><p>返回：</p><ul><li>this</li></ul></div></details><details><summary>addEventListener(events, handler, context)</summary><div><br><p>同 on 方法</p><p>返回：</p><ul><li>this</li></ul></div></details><details><summary>once(events, handler, context)</summary><div><br><p>注册图形的监听事件，响应后即删除</p><p>返回：</p><ul><li>this</li></ul></div></details><details><summary>off(events, handler, context)</summary><div><br><p>移除图形注册的监听事件</p><p>返回：</p><ul><li>this</li></ul></div></details><details><summary>removeEventListener(events, handler, context)</summary><div><br><p>同 off 方法</p><p>返回：</p><ul><li>this</li></ul></div></details><details><summary>listens(events, handler, context)</summary><div><br><p>判断图形是否监听了events事件。</p><p>返回：</p><ul><li>Boolean</li></ul></div></details><details><summary>fire(event, params)</summary><div><br><p>手动发射一个事件，params是时间参数。</p><p>返回：</p><ul><li>this</li></ul></div></details><details><summary>setOptions(options)</summary><div><br><p>设置图形配置。</p><p>返回：</p><ul><li>this</li></ul></div></details><details><summary>config(key, value)</summary><div><br><p>更新某个图形配置。</p><p>返回：</p><ul><li>this</li></ul></div></details><details><summary>getJSONType()</summary><div><br><p>返回图形类注册的JSON type。</p><p>返回：</p><ul><li>String</li></ul></div></details>',63)])])}const g=l(r,[["render",o]]);export{y as __pageData,g as default};
